[{"order":1,"type":"heading","text":"Akita: State Management in Angular"},{"order":2,"type":"paragraph","text":"Akita is a state management pattern built on top of RxJS. It's designed to be simple, flexible, and easy to learn, making it a great alternative to more complex solutions like NgRx or Redux. Akita promotes a predictable and maintainable state management approach for Angular applications."},{"order":3,"type":"subheading","text":"Key Concepts"},{"order":4,"type":"bullet_point","text":"Store: Holds the application state. It's a single source of truth for your data."},{"order":5,"type":"bullet_point","text":"Query: Used to select and derive data from the store. Queries are memoized, meaning they only re-execute when the underlying data changes."},{"order":6,"type":"bullet_point","text":"Entity Store: A specialized store for managing collections of entities (objects with unique IDs)."},{"order":7,"type":"bullet_point","text":"Entity Query: A specialized query for querying entity stores."},{"order":8,"type":"bullet_point","text":"Service: Contains the business logic for updating the store. Services are responsible for interacting with APIs and dispatching actions to modify the state."},{"order":9,"type":"subheading","text":"Setting up Akita"},{"order":10,"type":"paragraph","text":"First, install Akita using npm or yarn:"},{"order":11,"type":"code","text":"npm install @datorama/akita --save"},{"order":12,"type":"subheading","text":"Creating a Store"},{"order":13,"type":"paragraph","text":"Let's create a simple store for managing a list of tasks. First, define the task interface:"},{"order":14,"type":"code","text":"export interface Task { id: string; title: string; completed: boolean; }"},{"order":15,"type":"paragraph","text":"Now, create the store:"},{"order":16,"type":"code","text":"import { Store, StoreConfig } from '@datorama/akita';

export interface TasksState { tasks: Task[]; }

@StoreConfig({ name: 'tasks' })
export class TasksStore extends Store<TasksState> {
  constructor() {
    super({ tasks: [] });
  }
}

export const tasksStore = new TasksStore();"},{"order":17,"type":"subheading","text":"Creating a Query"},{"order":18,"type":"paragraph","text":"Create a query to select tasks from the store:"},{"order":19,"type":"code","text":"import { Query } from '@datorama/akita';
import { TasksState } from './tasks.store';
import { Observable } from 'rxjs';
import { Task } from './task.model';

export class TasksQuery extends Query<TasksState> {
  constructor(protected store: TasksStore) {
    super(store);
  }

  getTasks(): Observable<Task[]> {
    return this.select(state => state.tasks);
  }
}

export const tasksQuery = new TasksQuery(tasksStore);"},{"order":20,"type":"subheading","text":"Creating a Service"},{"order":21,"type":"paragraph","text":"Create a service to update the store:"},{"order":22,"type":"code","text":"import { Injectable } from '@angular/core';
import { tasksStore, TasksStore } from './tasks.store';
import { Task } from './task.model';
import { ID } from '@datorama/akita';

@Injectable({ providedIn: 'root' })
export class TasksService {
  constructor(private tasksStore: TasksStore) {}

  addTask(task: Task) {
    this.tasksStore.update(state => ({
      tasks: [...state.tasks, task]
    }));
  }

  updateTask(id: ID, task: Partial<Task>) {
    this.tasksStore.update(state => ({
      tasks: state.tasks.map(t => (t.id === id ? { ...t, ...task } : t))
    }));
  }

  removeTask(id: ID) {
    this.tasksStore.update(state => ({
      tasks: state.tasks.filter(t => t.id !== id)
    }));
  }
}"},{"order":23,"type":"subheading","text":"Using Akita in a Component"},{"order":24,"type":"paragraph","text":"Inject the service and query into your component:"},{"order":25,"type":"code","text":"import { Component, OnInit } from '@angular/core';
import { TasksService } from './tasks.service';
import { TasksQuery } from './tasks.query';
import { Observable } from 'rxjs';
import { Task } from './task.model';

@Component({
  selector: 'app-tasks',
  template: `
    <ul>
      <li *ngFor="let task of tasks$ | async">{{ task.title }}</li>
    </ul>
  `,
  styleUrls: ['./tasks.component.css']
})
export class TasksComponent implements OnInit {
  tasks$: Observable<Task[]>;

  constructor(private tasksService: TasksService, private tasksQuery: TasksQuery) {}

  ngOnInit() {
    this.tasks$ = this.tasksQuery.getTasks();

    // Example: Add a task
    this.tasksService.addTask({ id: '1', title: 'Learn Akita', completed: false });
  }
}"},{"order":26,"type":"subheading","text":"Entity Store and Query"},{"order":27,"type":"paragraph","text":"For managing collections of entities, Akita provides `EntityStore` and `EntityQuery`. These classes simplify common operations like adding, updating, and removing entities. The `EntityStore` requires you to define an `idKey` in the `@StoreConfig` decorator. The default value is 'id'."},{"order":28,"type":"code","text":"import { EntityStore, StoreConfig } from '@datorama/akita';

export interface TasksState {
}

@StoreConfig({ name: 'tasks', idKey: 'taskId' })
export class TasksStore extends EntityStore<TasksState, Task> {
  constructor() {
    super();
  }
}"},{"order":29,"type":"paragraph","text":"The service methods change slightly when using an EntityStore:"},{"order":30,"type":"code","text":"import { Injectable } from '@angular/core';
import { TasksStore } from './tasks.store';
import { Task } from './task.model';
import { ID } from '@datorama/akita';

@Injectable({ providedIn: 'root' })
export class TasksService {
  constructor(private tasksStore: TasksStore) {}

  addTask(task: Task) {
    this.tasksStore.add(task);
  }

  updateTask(id: ID, task: Partial<Task>) {
    this.tasksStore.update(id, task);
  }

  removeTask(id: ID) {
    this.tasksStore.remove(id);
  }
}"},{"order":31,"type":"subheading","text":"Conclusion"},{"order":32,"type":"paragraph","text":"Akita offers a straightforward and efficient approach to state management in Angular. Its simple API and powerful features make it a valuable tool for building scalable and maintainable applications. Remember to explore the official Akita documentation for more advanced features and best practices."}]
